const getPoints=async()=>{const saleSeries={name:"Total Sale",points:[]};const earningSeries={name:"Total Earnings",points:[]};try{const res=await axios.get("/user/books/analytics");saleSeries.points=res.data.saleSeriesPoints;earningSeries.points=res.data.earningSeriesPoints;return{saleSeries:saleSeries,earningSeries:earningSeries}}catch(error){console.log(error)}};getPoints().then(result=>{const totalProductsSoldChart=JSC.chart("sellerTotalProductsSoldChart",{debug:false,type:"area",legend:{template:"%icon %name",position:"inside top left"},defaultPoint_marker_type:"none",xAxis_crosshair_enabled:true,series:[result.saleSeries]});const totalEarningsChart=JSC.chart("sellerTotalEarningsChart",{debug:false,type:"area",legend:{template:"%icon %name",position:"inside top left"},defaultPoint_marker_type:"none",xAxis_crosshair_enabled:true,series:[result.earningSeries]})});